// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t1, uint256 t2, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        t1 = bound(t1, 1, 500);
        t2 = bound(t2, t1 + 1, 999);

        // Park execution at a block number well above both timestamps.
        vm.roll(1000);

        // First successful fallback call at timestamp t1.
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // Second call at a strictly later timestamp t2, still in a block
        // whose number (1000) is >= t2. The reference stored t1 (< t2), so
        // the call succeeds; the mutant stored 1000, so it reverts.
        vm.warp(t2);
        vm.roll(1000);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        assertTrue(ok2, "second fallback at a later timestamp must succeed");
    }
}
